/**
 * The OCI runtime provider.
 *
 * One implementation, two clients: `docker` for a developer workstation and
 * `nerdctl` for a Linux host running containerd, where `runsc` (gVisor) is
 * registered as a runtime handler. The flags are identical because both clients
 * speak the same contract; the only difference is the runtime's name.
 *
 * This is deliberately *not* a generic "run any OCI config" provider. It accepts
 * `RuntimeSandboxConfig`, a closed structure with no field for a capability, a
 * mount, a namespace, a device or a runtime binary. The argv is generated by
 * `oci-args.ts` and asserted against the baseline before it is spawned.
 *
 * gVisor is never a fallback. When the policy requires gVisor and the daemon
 * cannot provide it, `probe()` reports the failure and `create()` refuses. On a
 * macOS developer machine the provider therefore runs with `runc` only when the
 * operator explicitly chose that weaker class; the runtime type is recorded on
 * every sandbox and shown by `/health`.
 */

import {
  type RuntimeExecutionRequest,
  type RuntimeExecutionResult,
  type RuntimeSandboxConfig,
  type RuntimeStatus,
  type SandboxHandle,
  type SandboxRuntime,
} from '../types.ts';
import { SandboxRuntimeUnavailableError } from '../errors.ts';
import { ContainerCli } from './container-cli.ts';
import {
  assertSafeName,
  buildCreateArgs,
  buildDestroyArgs,
  buildExecArgs,
  buildInspectArgs,
  buildInterruptArgs,
  buildProbeArgs,
  buildReadMarkerArgs,
  buildStartArgs,
  sandboxContainerName,
  type ContainerCliOptions,
} from './oci-args.ts';

export interface OciRuntimeOptions extends ContainerCliOptions {
  readonly cli?: ContainerCli;
}

interface DockerState {
  readonly Status?: string;
  readonly Running?: boolean;
  readonly ExitCode?: number;
  readonly StartedAt?: string;
  readonly FinishedAt?: string;
}

export class OciRuntime implements SandboxRuntime {
  readonly type: string;
  private readonly cli: ContainerCli;
  private readonly options: ContainerCliOptions;

  constructor(options: OciRuntimeOptions) {
    this.options = options;
    this.cli = options.cli ?? new ContainerCli({
      binary: options.binary,
      kind: options.kind,
      ...(options.globalArgs.length > 0 ? { globalArgs: options.globalArgs } : {}),
    });
    this.type = options.kind === 'docker' ? 'docker' : 'containerd';
  }

  async probe(): Promise<{ ok: boolean; detail: string }> {
    try {
      let result = await this.cli.run(buildProbeArgs(this.options.kind), {
        timeoutMs: 10_000,
        maxOutputBytes: 256 * 1024,
      });
      if (result.code !== 0 && this.options.kind === 'nerdctl') {
        // Older nerdctl versions do not accept `--format` on `info`; a plain
        // info run is still enough to see whether runsc is mentioned.
        result = await this.cli.run(['info'], { timeoutMs: 10_000, maxOutputBytes: 256 * 1024 });
      }
      if (result.code !== 0) {
        return { ok: false, detail: (result.stderr || 'runtime probe failed').trim().slice(0, 300) };
      }
      if (this.options.kind === 'docker') {
        const runtimes = JSON.parse(result.stdout) as Record<string, unknown>;
        const names = Object.keys(runtimes).map((name) => name.toLowerCase());
        if (names.length === 0) {
          return { ok: false, detail: 'docker reports no OCI runtimes' };
        }
        const hasGvisor = names.some((name) => name.includes('runsc') || name.includes('gvisor'));
        return {
          ok: true,
          detail: `available runtimes: ${names.join(', ')}; gvisor=${hasGvisor ? 'present' : 'absent'}`,
        };
      }
      // nerdctl's info JSON is not a stable shape across versions; the honest
      // check for a gVisor handler is whether the daemon mentions runsc at all.
      const mentionsGvisor = /runsc|gvisor/i.test(result.stdout);
      return {
        ok: true,
        detail: `containerd reachable; gvisor=${mentionsGvisor ? 'present' : 'absent'}`,
      };
    } catch (error) {
      return { ok: false, detail: error instanceof Error ? error.message : String(error) };
    }
  }

  /** A probe that fails closed for the requested runtime class. */
  async probeFor(runtimeClass: 'gvisor' | 'runc' | 'default'): Promise<{ ok: boolean; detail: string }> {
    const probe = await this.probe();
    if (!probe.ok) return probe;
    if (runtimeClass !== 'gvisor') return probe;

    const hasGvisor = probe.detail.includes('gvisor=present');
    return hasGvisor
      ? probe
      : {
          ok: false,
          detail:
            'gVisor/runsc is required by policy but is not registered with the container runtime; ' +
            'refusing to fall back to runc',
        };
  }

  async create(config: RuntimeSandboxConfig): Promise<SandboxHandle> {
    if (config.runtimeClass === 'gvisor') {
      const probe = await this.probeFor('gvisor');
      if (!probe.ok) throw new SandboxRuntimeUnavailableError(probe.detail);
    }
    const containerName = sandboxContainerName(config.sandboxId);
    assertSafeName('sandbox id', config.sandboxId);

    // A stopped container from a previous incarnation holds the name. Removing it
    // is part of rebuilding a sandbox: workspace state lives outside the
    // container, so the runtime is disposable by design. Only a container this
    // platform labelled is removed; a same-named foreign container is left alone
    // and the create fails loudly instead of deleting someone else's workload.
    const existingLabel = await this.cli
      .run(
        ['inspect', '--format', '{{index .Config.Labels "eunoia.managed"}}', containerName],
        { timeoutMs: 10_000, allowNonZero: true, maxOutputBytes: 4_096 },
      )
      .catch(() => null);
    if (existingLabel?.code === 0 && existingLabel.stdout.trim() === 'true') {
      await this.cli
        .run(buildDestroyArgs(containerName), { timeoutMs: 30_000, allowNonZero: true })
        .catch(() => undefined);
    }

    await this.cli.withEnvFile(config.env, async (envFile) => {
      const args = buildCreateArgs(config, this.options, envFile);
      const result = await this.cli.run(args, {
        timeoutMs: 120_000,
        maxOutputBytes: 256 * 1024,
      });
      if (result.code !== 0) {
        throw new SandboxRuntimeUnavailableError(
          `could not create sandbox container: ${(result.stderr || result.stdout).trim().slice(0, 500)}`,
        );
      }
    });

    return { sandboxId: config.sandboxId, runtimeId: containerName, runtimeType: this.type };
  }

  async start(handle: SandboxHandle): Promise<void> {
    const status = await this.inspect(handle);
    if (!status.exists) {
      throw new SandboxRuntimeUnavailableError(`sandbox container is missing: ${handle.runtimeId}`);
    }
    if (status.running) return;
    await this.cli.runChecked(buildStartArgs(handle.runtimeId), { timeoutMs: 30_000 });
  }

  async execute(
    handle: SandboxHandle,
    request: RuntimeExecutionRequest,
  ): Promise<RuntimeExecutionResult> {
    const startedAt = new Date().toISOString();
    let result: Awaited<ReturnType<ContainerCli['run']>> | undefined;
    await this.cli.withEnvFile(request.env, async (envFile) => {
      const withEnv = buildExecArgs({
        containerName: handle.runtimeId,
        command: request.command,
        shell: request.shell,
        cwd: request.cwd,
        workspaceRoot: request.workspaceRoot,
        executionId: request.executionId,
        envFile,
      });
      result = await this.cli.run(withEnv, {
        timeoutMs: request.timeoutMs,
        maxOutputBytes: request.maxOutputBytes,
        ...(request.signal ? { signal: request.signal } : {}),
      });
    });

    const finishedAt = new Date().toISOString();
    if (!result) {
      return {
        status: 'UNKNOWN',
        exitCode: null,
        stdout: '',
        stderr: '',
        startedAt,
        finishedAt,
        timedOut: false,
        detail: 'container client produced no result',
      };
    }

    if (result.aborted) {
      await this.interrupt(handle, request.executionId).catch(() => undefined);
      return {
        status: 'CANCELLED',
        exitCode: null,
        stdout: result.stdout,
        stderr: result.stderr,
        startedAt,
        finishedAt,
        timedOut: false,
      };
    }

    if (result.timedOut) {
      // A timeout is enforced by killing the sandbox, not just the CLI: killing
      // `docker exec` leaves the process running inside the container.
      await this.interrupt(handle, request.executionId).catch(() => undefined);
      return {
        status: 'TIMEOUT',
        exitCode: null,
        stdout: result.stdout,
        stderr: result.stderr,
        startedAt,
        finishedAt,
        timedOut: true,
        detail: `execution exceeded ${request.timeoutMs}ms and the sandbox was terminated`,
      };
    }

    const runtimeGone = /no such container|is not running|cannot connect to the docker daemon|container .* is not running/i.test(
      result.stderr,
    );
    if (runtimeGone && result.code !== 0) {
      throw new SandboxRuntimeUnavailableError(
        `sandbox is no longer available: ${result.stderr.trim().slice(0, 300)}`,
      );
    }

    const exitCode = result.code;
    // The launcher refuses a directory it cannot resolve safely. That is not the
    // command failing; it is the execution context failing, and the Gateway needs
    // to tell the two apart so it can mark the task's cwd invalid.
    const cwdRejected = exitCode === 126 && /eunoia:cwd_rejected:/.test(result.stderr);
    return {
      status: exitCode === 0 ? 'SUCCEEDED' : exitCode === null ? 'UNKNOWN' : 'FAILED',
      exitCode,
      stdout: result.stdout,
      stderr: result.stderr,
      startedAt,
      finishedAt,
      timedOut: false,
      ...(cwdRejected ? { detail: 'cwd-rejected' } : {}),
    };
  }

  async inspect(handle: SandboxHandle): Promise<RuntimeStatus> {
    let result;
    try {
      result = await this.cli.run(buildInspectArgs(handle.runtimeId), {
        timeoutMs: 15_000,
        maxOutputBytes: 64 * 1024,
      });
    } catch (error) {
      throw error instanceof SandboxRuntimeUnavailableError
        ? error
        : new SandboxRuntimeUnavailableError(String(error));
    }
    if (result.code !== 0) {
      const missing = /no such (object|container)/i.test(result.stderr);
      return {
        exists: false,
        running: false,
        exitCode: null,
        detail: missing ? 'container does not exist' : result.stderr.trim().slice(0, 300),
      };
    }
    let state: DockerState;
    try {
      state = JSON.parse(result.stdout) as DockerState;
    } catch {
      return { exists: false, running: false, exitCode: null, detail: 'unparseable inspect output' };
    }
    return {
      exists: true,
      running: state.Running === true,
      exitCode: typeof state.ExitCode === 'number' ? state.ExitCode : null,
      detail: state.Status ?? '',
    };
  }

  async interrupt(handle: SandboxHandle, _executionId: string): Promise<void> {
    void _executionId;
    // Killing the container also kills every process the execution spawned. That
    // is heavier than targeting one PID, but it cannot be evaded by a child that
    // re-parents itself, and the sandbox is cheap to recreate.
    await this.cli
      .run(buildInterruptArgs(handle.runtimeId), { timeoutMs: 15_000, allowNonZero: true })
      .catch(() => undefined);
  }

  async readExitMarker(handle: SandboxHandle, executionId: string): Promise<number | null> {
    try {
      const result = await this.cli.run(buildReadMarkerArgs(handle.runtimeId, executionId), {
        timeoutMs: 10_000,
        maxOutputBytes: 4_096,
      });
      if (result.code !== 0) return null;
      const text = result.stdout.trim();
      if (!/^-?\d+$/.test(text)) return null;
      const value = Number.parseInt(text, 10);
      return Number.isFinite(value) ? value : null;
    } catch {
      return null;
    }
  }

  async destroy(handle: SandboxHandle): Promise<void> {
    await this.cli
      .run(buildDestroyArgs(handle.runtimeId), { timeoutMs: 30_000, allowNonZero: true })
      .catch(() => undefined);
  }
}

export function createOciRuntime(options: OciRuntimeOptions): SandboxRuntime {
  return new OciRuntime(options);
}
